// Synthetic Crew Intelligence data (Phase 1a). Everything here is fabricated: crew identifiers are
// built at runtime from counters (never stored as literals), names are placeholders, schedules are
// generated by a seeded PRNG. Nothing is derived from a real roster.
import { createHash, createHmac } from 'node:crypto';
import { gzipSync, gunzipSync } from 'node:zlib';
import { localDate } from '../gs-harness.js';

export const TZ = 'Europe/Berlin';
const H = 3600000;

export function rng(seed) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/** A synthetic employee-number-shaped identifier, built at runtime (never a literal in the repository). */
export const synthId = (n) => String(300000 + n) + String.fromCharCode(65 + (n % 26));
export const SELF = synthId(999);

function offsetMs(ms) {
  const p = new Intl.DateTimeFormat('en-CA', { timeZone: TZ, hourCycle: 'h23', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' })
    .formatToParts(new Date(ms)).reduce((o, x) => ({ ...o, [x.type]: x.value }), {});
  return Date.UTC(+p.year, +p.month - 1, +p.day, +p.hour, +p.minute) - (ms - (ms % 60000));
}

/** Node implementations of the injected primitives (Apps Script would use Utilities). */
export function cryptoDeps(pepper = 'synthetic-pepper-0123456789abcdef') {
  return {
    hash: (s) => createHash('sha256').update(String(s)).digest('hex'),
    keyOf: (id) => createHmac('sha256', pepper).update(String(id)).digest('base64url').slice(0, 22),   // 128 bits
    pack: (s) => gzipSync(Buffer.from(s, 'utf8')).toString('base64'),
    unpack: (s) => gunzipSync(Buffer.from(s, 'base64')).toString('utf8'),
    monthStart: (month) => {
      const guess = Date.UTC(+month.slice(0, 4), +month.slice(5, 7) - 1, 1);
      let t = guess - offsetMs(guess);
      t = guess - offsetMs(t);
      return t;
    },
    monthOf: (ms) => localDate(ms, TZ).slice(0, 7),
  };
}

let seq = 0;
/** One synthetic flight. crew: array of crew entries or null (no crew list). */
export function flight(dep, arr, origin, destination, crew, opts = {}) {
  seq += 1;
  return { sourceId: opts.id ?? `src-${seq}`, start: Date.parse(dep), end: Date.parse(arr), origin, destination, flightNumber: opts.fn ?? `DE${1000 + seq}`, crew };
}

/** Letters-only suffix for synthetic names (real names contain no digits; the parser rejects them). */
export const letters = (n) => { let s = ''; let x = n + 1; while (x > 0) { x -= 1; s = String.fromCharCode(65 + (x % 26)) + s; x = Math.floor(x / 26); } return s; };
export const member = (n, rank = 'FA') => ({ rank, id: synthId(n), family: `SAMPLE${letters(n)}`, given: `PERSON${letters(n)}` });
export const owner = () => ({ rank: 'FA', id: SELF, family: 'OWNER', given: 'SYNTHETIC' });
export const crewOf = (...ns) => [owner(), ...ns.map((n) => member(n))];

/** A calendar reader with OVERLAP semantics (as CalendarApp.getEvents). */
export function reader(flights, hidden = [], calls = []) {
  return (from, to) => {
    calls.push([from, to]);
    return { flights: flights.filter((f) => f.end > from && f.start < to), hidden: hidden.filter((h) => h.end > from && h.start < to) };
  };
}

/**
 * A realistic synthetic history: one FRA-based cabin crew member, Aug 2022 → end of `until`.
 * Short-haul days (2 or 4 sectors, 6 crew) and long-haul rotations (out, 2–3 day layover, overnight
 * return across midnight, 12 crew, same crew both ways). Colleagues come from synthetic pools with a
 * recency bias so that repeat pairings occur.
 */
export function generateHistory({ seed = 7, from = '2022-08-01', until = '2026-10-31' } = {}) {
  const r = rng(seed);
  const pick = (a) => a[Math.floor(r() * a.length)];
  const cockpitPool = 700;
  const cabinPool = 2600;
  const recent = { cockpit: [], cabin: [] };
  const draw = (kind, taken) => {
    for (;;) {
      const pool = kind === 'cockpit' ? cockpitPool : cabinPool;
      const base = kind === 'cockpit' ? 0 : cockpitPool;
      const list = recent[kind];
      const n = list.length > 20 && r() < 0.3 ? pick(list) : base + Math.floor(r() * pool);
      if (taken.has(n)) continue;
      taken.add(n);
      list.push(n);
      if (list.length > 200) list.shift();
      return n;
    }
  };
  const crew = (cockpit, cabin) => {
    const taken = new Set();
    const ranks = ['CP', 'FO', 'SFO'];
    const out = [owner()];
    for (let i = 0; i < cockpit; i++) out.push(member(draw('cockpit', taken), ranks[i]));
    out.push(member(draw('cabin', taken), 'PU'));
    for (let i = 0; i < cabin - 2; i++) out.push(member(draw('cabin', taken), 'FA'));
    return out;
  };
  const short = ['PMI', 'LPA', 'HER', 'AYT', 'FUE', 'TFS', 'ACE', 'RHO', 'SPU', 'OLB'];
  const long = ['PUJ', 'CUN', 'MBA', 'BKK', 'SEA', 'JFK'];
  const flights = [];
  let n = 0;
  let lastEnd = 0;                                    // keep at least a 12 h rest between duties (realistic FTL)
  const add = (dep, block, o, d, c) => {
    n += 1;
    flights.push({ sourceId: `hist-${n}`, start: dep, end: dep + block, origin: o, destination: d, flightNumber: `DE${1000 + (n % 8000)}`, crew: c });
    lastEnd = dep + block;
    return dep + block;
  };
  const end = Date.parse(`${until}T23:59:00Z`);
  for (let day = Date.parse(`${from}T00:00:00Z`); day < end;) {
    const x = r();
    if (x < 0.42) { day += 24 * H; continue; }
    if (x < 0.82) {
      const c = crew(2, 4);
      let t = Math.max(day + (5 + Math.floor(r() * 3)) * H, lastEnd + 12 * H);
      const legs = r() < 0.7 ? 1 : 2;
      for (let i = 0; i < legs; i++) {
        const dst = pick(short);
        const block = (legs === 2 ? 1.5 + r() : 2 + r() * 2.5) * H;
        t = add(t, block, 'FRA', dst, c) + (50 + r() * 20) * 60000;
        t = add(t, block, dst, 'FRA', c) + (50 + r() * 20) * 60000;
      }
      day += 24 * H;
      continue;
    }
    const c = crew(3, 9);
    const dst = pick(long);
    add(Math.max(day + 9 * H, lastEnd + 12 * H), (8 + r() * 3) * H, 'FRA', dst, c);
    const layover = 2 + Math.floor(r() * 2);
    add(day + layover * 24 * H + 21 * H, (8 + r() * 2) * H, dst, 'FRA', c);
    day += (layover + 2) * 24 * H;
  }
  return flights;
}

/** A property store with documented limits (value ≤ 9,000 chars here, total ≤ 500,000 bytes) and fault injection. */
export function fakeStore(initial = {}) {
  const map = new Map(Object.entries(initial));
  const faults = { set: null, del: null };
  const bytes = () => [...map].reduce((s, [k, v]) => s + Buffer.byteLength(k) + Buffer.byteLength(v), 0);
  return {
    map, faults,
    keys: () => [...map.keys()],
    get: (k) => (map.has(k) ? map.get(k) : null),
    set: (k, v) => {
      if (faults.set && faults.set(k, v)) throw new Error('injected write failure');
      if (v.length > 9000) throw new Error('value too large');
      const before = map.has(k) ? Buffer.byteLength(k) + Buffer.byteLength(map.get(k)) : 0;
      if (bytes() - before + Buffer.byteLength(k) + Buffer.byteLength(v) > 500000) throw new Error('quota exceeded');
      map.set(k, v);
    },
    del: (k) => {
      if (faults.del && faults.del(k)) throw new Error('injected delete failure');
      map.delete(k);
    },
    bytes,
  };
}

// --- Phase 1b: raw calendar events, handler dependencies -------------------------------------------

/** Start of a base-zone local day (ms). */
export function dayStart(key) {
  const guess = Date.parse(`${key}T00:00:00Z`);
  let t = guess - offsetMs(guess);
  t = guess - offsetMs(t);
  return t;
}

/** Handler dependencies: Node versions of what Apps Script would provide through Utilities. */
export function handlerDeps() {
  let n = 0;
  const base = cryptoDeps();
  return {
    ...base,
    hmacHex: (pepper, text) => createHmac('sha256', pepper).update(String(text)).digest('hex'),
    hmacKey: (pepper, text) => createHmac('sha256', pepper).update(String(text)).digest('base64url').slice(0, 22),
    localDate: (ms) => localDate(ms, TZ),
    dayStart,
    newId: () => `epoch${String(++n).padStart(4, '0')}`,
  };
}

/** A crew-list line in the airline's layout, built at runtime from synthetic entries. */
export const crewLine = (c) => (c.parseFailed ? 'CP ### broken line' : `${c.rank} ${c.id ? `${c.id} ` : ''}${c.family}, ${c.given} (FRA)`);

/**
 * A raw calendar event for a synthetic flight. synced: the v5 synced-copy form (title prefix, enriched
 * description with a v5 "CREW HISTORY" block and the original text under "Original Notes:").
 */
export function toRaw(f, { synced = false } = {}) {
  const lines = [`${f.origin} SAMPLE AIRPORT ${f.origin}`, `${f.destination} SAMPLE AIRPORT ${f.destination}`, '', 'DABCD (32N)', ''];
  if (f.crew) lines.push(...f.crew.map(crewLine));
  lines.push('', 'Booking code: SAMPLE9');
  const original = lines.join('\n');
  const title = `${f.flightNumber} ${f.origin}-${f.destination}`;
  if (!synced) return { sourceId: f.sourceId, title, start: f.start, end: f.end, location: f.origin, description: original };
  const v5 = f.crew && f.crew[1]?.id ? `\n\n👥 CREW HISTORY\n\n😊 Colleague ${f.crew[1].id}\n   • Flown together 3 times\n` : '';
  return { sourceId: f.sourceId, title: `✈️✈️✈️ ${title}`, start: f.start, end: f.end, location: f.origin,
    description: `✈️ Flight ${title}\n   Weather: sample${v5}\n---\nOriginal Notes:\n${original}` };
}
